var ICON_NAMES = [];
for (var _k in ICONS) ICON_NAMES.push(_k);

/* =====================================================================
 * UI 层 emoji → 内联 SVG 图标（运行时替换）
 * ---------------------------------------------------------------------
 * 为什么不在源码里一个个把 emoji 换成 icon() 调用：
 *   界面的 HTML 是 40 多个模板函数拼出来的，emoji 散在 200 多处字符串里，
 *   逐个改既容易漏、又会让 diff 变得没法 review。这里换成"渲染后扫一遍"：
 *   任何一次 innerHTML 重绘 / 流式追加都会触发，合并到下一帧统一替换。
 *
 * ★ 只换 UI，不换内容：正文（.body/.md）、代码（pre/code）、终端输出、
 *   输入框、AI 回复、题面/解析里的 emoji 是"内容"，必须原样保留 ——
 *   那些是讲义和 AI 写的东西，不是界面控件。
 * ★ 幂等：换完的节点里已经没有 emoji 了，所以不会自己触发自己形成死循环。
 * =================================================================== */
var EMOJI_SKIP = ".body,.md,pre,code,kbd,textarea,input,select," +
  ".rl-out,.rl-in,.replOut,.replIn,.cnDetail,.cnRawPlain,.cnRaw pre," +
  ".vfyBox,.miniPre,.resGrid pre,.allCase,.codeBlock pre,.runCode,.probCode,.asBubble pre";
/* 给"这段文本里有没有需要替换的 emoji"用的快速判断（按 IEMOJI 的键来，不猜 Unicode 区间） */
function _hasUiEmoji(s){
  if (!s) return false;
  for (var i = 0; i < s.length; i++){
    var two = s.substr(i, 2);
    if (IEMOJI[two]) return true;
    if (IEMOJI[s.charAt(i)]) return true;
  }
  return false;
}
/* 把一个文本节点的内容换成"文字 + 图标 span"混合的 fragment */
function _emojiNode(txt){
  var frag = document.createDocumentFragment();
  var buf = "", i = 0, hit = 0;
  while (i < txt.length){
    var two = txt.substr(i, 2), one = txt.charAt(i), name = IEMOJI[two] || IEMOJI[one];
    if (!name){
      /* 成对的 surrogate 必须整体保留，否则单个代理项会变成乱码方块 */
      var code = txt.charCodeAt(i);
      if (code >= 0xD800 && code <= 0xDBFF && i + 1 < txt.length){
        buf += txt.substr(i, 2); i += 2; continue;
      }
      buf += one; i += 1; continue;
    }
    if (buf){ frag.appendChild(document.createTextNode(buf)); buf = ""; }
    var span = document.createElement("span");
    span.className = "emo";
    span.innerHTML = icon(name);        /* icon() 的产物是本地字面量，没有外部输入 */
    frag.appendChild(span);
    i += IEMOJI[two] ? 2 : 1;
    hit++;
  }
  if (buf) frag.appendChild(document.createTextNode(buf));
  return hit ? frag : null;
}
function uiEmojiSwap(root){
  root = root || document.body;
  if (!root || !document.createTreeWalker) return 0;
  var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: function(n){
      var p = n.parentNode;
      if (!p || p.nodeType !== 1) return NodeFilter.FILTER_REJECT;
      var tag = String(p.tagName || "").toUpperCase();
      if (tag === "SCRIPT" || tag === "STYLE" || tag === "TEXTAREA" || tag === "INPUT" || tag === "OPTION"){
        return NodeFilter.FILTER_REJECT;
      }
      var skip = false;
      try{ skip = !!(p.closest && p.closest(EMOJI_SKIP)); }catch(e){ skip = false; }
      if (skip) return NodeFilter.FILTER_REJECT;
      return _hasUiEmoji(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    }
  }, false);
  var nodes = [], n, count = 0;
  while ((n = walker.nextNode())) nodes.push(n);
  for (var k = 0; k < nodes.length; k++){
    var frag = _emojiNode(nodes[k].nodeValue);
    if (!frag) continue;
    if (nodes[k].parentNode) nodes[k].parentNode.replaceChild(frag, nodes[k]);
    count++;
  }
  return count;
}
/* 合并到下一帧统一扫（流式输出时一个 token 触发一次扫描太浪费） */
var _emojiSweepPending = false;
function uiEmojiSweep(){
  if (_emojiSweepPending) return;
  _emojiSweepPending = true;
  var run = function(){ _emojiSweepPending = false; try{ uiEmojiSwap(document.body); }catch(e){} };
  if (window.requestAnimationFrame) window.requestAnimationFrame(run);
  else setTimeout(run, 16);
}
try{
  var _emojiMO = new MutationObserver(uiEmojiSweep);
  _emojiMO.observe(document.body, { childList:true, subtree:true, characterData:true });
}catch(e){ /* 没有 MutationObserver：至少首屏扫一次 */
  setTimeout(uiEmojiSweep, 30);
}
uiEmojiSweep();
